import React, { useEffect, useState } from 'react';
import { createRoot } from 'react-dom/client';
import './styles.css';
import './smart.css';
import './flight-search.css';
import './booking.css';

const API = import.meta.env.VITE_API_URL || 'http://localhost:4000/api';
const Glyph = ({ children }) => <span className="icon-glyph" aria-hidden="true">{children}</span>;
const Icons = { plane: () => <Glyph>✈</Glyph>, home: () => <Glyph>▦</Glyph>, flights: () => <Glyph>◷</Glyph>, trips: () => <Glyph>▣</Glyph>, bag: () => <Glyph>▤</Glyph>, assistant: () => <Glyph>✦</Glyph>, map: () => <Glyph>⌖</Glyph>, services: () => <Glyph>◇</Glyph>, control: () => <Glyph>⌁</Glyph>, queues: () => <Glyph>≋</Glyph>, verification: () => <Glyph>✓</Glyph>, help: () => <Glyph>?</Glyph>, logout: () => <Glyph>↪</Glyph>, users: () => <Glyph>♙</Glyph>, bell: () => <Glyph>●</Glyph>, refresh: () => <Glyph>↻</Glyph>, shield: () => <Glyph>✓</Glyph> };

let refreshInFlight = null;
async function request(path, options = {}, hasRetried = false) { const response = await fetch(API + path, { ...options, headers: { 'Content-Type': 'application/json', ...(options.headers || {}), ...(localStorage.token && !options.headers?.Authorization ? { Authorization: `Bearer ${localStorage.token}` } : {}) } }); const data = await response.json().catch(() => ({})); if (response.status === 401 && !hasRetried && localStorage.refreshToken && !path.startsWith('/auth/')) { refreshInFlight ||= fetch(`${API}/auth/refresh`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ refreshToken: localStorage.refreshToken }) }).then(async result => { const session = await result.json().catch(() => ({})); if (!result.ok) throw Error(session.error || 'Session expired'); localStorage.token = session.token; localStorage.refreshToken = session.refreshToken; localStorage.user = JSON.stringify(session.user); return session; }).finally(() => { refreshInFlight = null; }); try { await refreshInFlight; return request(path, options, true); } catch { localStorage.clear(); window.dispatchEvent(new Event('skyflow:session-expired')); throw Error('Session expired. Please sign in again.'); } } if (!response.ok) throw Error(data.error || 'Request failed'); return data; }

function Login({ onLogin }) { const [role, setRole] = useState('passenger'); const [email, setEmail] = useState(demo.passenger[0]); const [password, setPassword] = useState(demo.passenger[1]); const [error, setError] = useState(''); const submit = async e => { e.preventDefault(); try { const result = await request('/auth/login', { method: 'POST', body: JSON.stringify({ email, password }) }); localStorage.token = result.token; onLogin(result.user); } catch (err) { setError(err.message); } }; return <main className="auth"><div className="runway"><div className="plane-float">✈</div></div><section className="login-card"><div className="brand"><Icons.plane/><span>SKYFLOW</span></div><p className="eyebrow">SMART INTERNATIONAL AIRPORT</p><h1>Travel, orchestrated.</h1><p className="muted">A connected airport experience for every journey.</p><div className="role-tabs">{Object.keys(demo).map(item => <button key={item} className={role === item ? 'active' : ''} onClick={() => { setRole(item); setEmail(demo[item][0]); setPassword(demo[item][1]); }}>{item}</button>)}</div><form onSubmit={submit}><label>Email<input value={email} onChange={e => setEmail(e.target.value)} type="email"/></label><label>Password<input value={password} onChange={e => setPassword(e.target.value)} type="password"/></label>{error && <div className="error">{error}</div>}<button className="primary">Sign in to SkyFlow <span>→</span></button></form><small>Demo access · {role}@skyflow.demo</small></section></main>; }

const passengerNav = [['overview', 'Overview', Icons.home], ['flights', 'Find flights', Icons.flights], ['trips', 'My trips', Icons.trips], ['baggage', 'Baggage', Icons.bag], ['assistant', 'Travel assistant', Icons.assistant], ['navigate', 'Airport guide', Icons.map], ['services', 'Services', Icons.services]];
const operationsNav = [['operations', 'Operations', Icons.home], ['flights', 'Flight management', Icons.flights], ['control', 'Control room', Icons.control], ['queues', 'Queues', Icons.queues], ['verification', 'Verification', Icons.verification], ['assistance', 'Assistance', Icons.help], ['passengers', 'Passengers', Icons.users], ['requests', 'Passenger requests', Icons.services]];

function App({ user, onLogout }) { const [page, setPage] = useState(user.role === 'passenger' ? 'overview' : 'operations'); const [flights, setFlights] = useState([]); const [me, setMe] = useState(null); const [dashboard, setDashboard] = useState(null); const [smart, setSmart] = useState(null); const [toast, setToast] = useState(''); const nav = user.role === 'passenger' ? passengerNav : operationsNav; const refresh = async () => { const [flightData, meData, smartData] = await Promise.all([request('/flights'), request('/me'), request('/smart/overview')]); setFlights(flightData.data); setMe(meData); setSmart(smartData); if (user.role !== 'passenger') setDashboard(await request('/dashboard')); }; useEffect(() => { refresh().catch(err => setToast(err.message)); }, []); const act = async action => { try { await action(); await refresh(); setToast('Updated successfully'); setTimeout(() => setToast(''), 2400); } catch (err) { setToast(err.message); } }; return <div className="app"><aside><div className="brand dark"><Icons.plane/><span>SKYFLOW</span></div><div className="workspace">{user.role.toUpperCase()} WORKSPACE</div><nav>{nav.map(([id, label, Icon]) => <button key={id} className={page === id ? 'selected' : ''} onClick={() => setPage(id)}><Icon/>{label}</button>)}</nav><div className="sidebar-bottom"><div className="user-mini"><div className="avatar">{user.name[0]}</div><div><b>{user.name}</b><small>{user.role}</small></div></div><button onClick={onLogout}><Icons.logout/> Sign out</button></div></aside><main className="content"><header><div><p className="eyebrow">{user.role === 'passenger' ? 'PASSENGER PORTAL' : 'AIRPORT CONTROL CENTRE'}</p><h2>{page === 'overview' ? `Good morning, ${user.name.split(' ')[0]}.` : nav.find(item => item[0] === page)?.[1]}</h2></div><div className="header-actions"><span className="live"><i/> Live simulation</span><button className="icon-button" onClick={() => act(refresh)}><Icons.refresh/></button><button className="icon-button"><Icons.bell/><em>{me?.notifications?.filter(item => !item.read).length || 0}</em></button></div></header>{toast && <div className="toast">{toast}</div>}{page === 'overview' && <PassengerHome me={me} flights={flights} smart={smart} act={act} setPage={setPage}/>} {page === 'trips' && <Trips me={me} flights={flights} act={act}/>} {page === 'baggage' && <Baggage me={me}/>} {page === 'flights' && (user.role === 'passenger' ? <FlightSearch/> : <FlightManagement flights={flights} act={act}/>)} {page === 'assistant' && <TravelAssistant smart={smart}/>} {page === 'navigate' && <Navigation smart={smart}/>} {page === 'services' && <Services smart={smart} act={act}/>} {page === 'operations' && <Operations dashboard={dashboard} flights={flights} act={act}/>} {page === 'control' && <ControlRoom smart={smart} flights={flights}/>} {page === 'queues' && <QueueBoard smart={smart} act={act}/>} {page === 'verification' && <Verification smart={smart} act={act}/>} {page === 'assistance' && <Assistance smart={smart} act={act}/>} {page === 'passengers' && <Passengers dashboard={dashboard}/>} {page === 'requests' && <AdminServiceRequests act={act}/>}</main></div>; }

function PassengerHome({ me, flights, smart, act, setPage }) { const booking = me?.bookings?.[0]; const flight = flights.find(item => item.id === booking?.flightId); return <><div className="hero-card"><div><span className="pill blue">UPCOMING JOURNEY</span><h3>{flight?.origin || '—'} <span>→</span> {flight?.destination || '—'}</h3><p>{flight?.airline || 'No active flight'} · {flight?.number || '—'} · {flight?.date || '—'}</p></div><div className="journey-meta"><b>{flight?.scheduled || '—'}</b><small>Departure</small></div><div className="journey-meta"><b>{flight?.gate || '—'}</b><small>Gate</small></div><div className="journey-meta"><b>{booking?.seat || '—'}</b><small>Seat</small></div></div><div className="smart-strip"><div><span className="pill blue">SMART JOURNEY ASSISTANT</span><h3>Need help with your next step?</h3><p>Personalized guidance based on your booking and live simulated flight data.</p></div><button className="secondary" onClick={() => setPage('assistant')}>Ask SkyFlow AI →</button></div><div className="grid two"><section className="panel"><div className="panel-title"><h3>Journey progress</h3><span className="pill green">{booking?.checkedIn ? 'CHECKED IN' : 'CHECK-IN OPEN'}</span></div><div className="journey-steps">{['Enter airport', 'Check-in', 'Security', 'Gate A12', 'Boarding'].map((step, index) => <div key={step} className={index < (booking?.checkedIn ? 3 : 1) ? 'done' : index === (booking?.checkedIn ? 3 : 1) ? 'current' : ''}><b>{index + 1}</b><span>{step}</span></div>)}</div>{booking && !booking.checkedIn && <button className="primary" onClick={() => act(() => request(`/bookings/${booking.id}/check-in`, { method: 'POST' }))}>Complete online check-in →</button>}</section><section className="panel"><div className="panel-title"><h3>Where should I go next?</h3><Icons.map/></div><p className="muted">Your route is marked as simulated and uses your current booking context.</p><div className="route-preview"><span>Current</span><b>T1 entrance</b><span>→</span><b>{flight?.gate || 'assigned gate'}</b></div><button className="secondary" onClick={() => setPage('navigate')}>Open accessible terminal guide</button></section></div></>; }

function TravelAssistant({ smart }) { const [question, setQuestion] = useState('What should I do next?'); const [answer, setAnswer] = useState(''); const [busy, setBusy] = useState(false); const ask = async e => { e.preventDefault(); setBusy(true); try { const result = await request('/smart/assistant', { method: 'POST', body: JSON.stringify({ question }) }); setAnswer(result.answer); } catch (err) { setAnswer(err.message); } finally { setBusy(false); } }; return <div className="assistant-layout"><section className="panel assistant-panel"><div className="assistant-orb">✦</div><span className="pill blue">SKYFLOW SMART ASSISTANT · SIMULATION</span><h3>Your airport co-pilot</h3><p className="muted">Ask about procedures, your current flight, baggage, queues or airport facilities. Answers use your account data when available and never invent flight details.</p><form onSubmit={ask} className="assistant-form"><input value={question} onChange={e => setQuestion(e.target.value)} placeholder="Ask a travel question…"/><button className="primary" disabled={busy}>{busy ? 'Thinking…' : 'Ask assistant'}</button></form>{answer && <div className="assistant-answer"><b>SkyFlow guidance</b><p>{answer}</p><small>Need a person? Airport support escalation is available from the assistance desk.</small></div>}</section><section className="panel"><div className="panel-title"><h3>Personalized checklist</h3><span className="pill green">{smart?.booking?.pnr || 'NO PNR'}</span></div>{['Travel document ready', 'Boarding pass available', 'Baggage allowance checked', 'Security queue reviewed', 'Gate and boarding time confirmed'].map((item, index) => <div className="check-row" key={item}><span className={index < 2 ? 'check done' : 'check'}>{index < 2 ? '✓' : ''}</span><span>{item}</span><small>{index < 2 ? 'Ready' : 'Recommended'}</small></div>)}</section></div>; }

function Navigation({ smart }) { const [facility, setFacility] = useState('Gate A12'); const [accessible, setAccessible] = useState(false); const [route, setRoute] = useState(null); const find = async () => setRoute(await request(`/smart/navigation?facility=${encodeURIComponent(facility)}&accessible=${accessible}`)); return <div className="grid two"><section className="panel"><div className="panel-title"><h3>Terminal guide</h3><span className="pill blue">SIMULATED MAP</span></div><p className="muted">T1 operations map · accessible wayfinding available</p><div className="terminal-map"><div className="map-label entrance">Entrance</div><div className="map-label check">Check-in</div><div className="map-label security">Security</div><div className="map-label gate">A12</div><div className="map-route"/></div><label>Where do you want to go?<select value={facility} onChange={e => setFacility(e.target.value)}>{smart?.facilities?.map(item => <option key={item.id}>{item.name}</option>)}</select></label><label className="toggle"><input type="checkbox" checked={accessible} onChange={e => setAccessible(e.target.checked)}/> Use wheelchair-accessible route</label><button className="primary" onClick={find}>Show directions →</button></section><section className="panel"><div className="panel-title"><h3>Step-by-step route</h3><Icons.map/></div>{route ? <><div className="route-summary"><b>{route.destination.name}</b><span>{route.walkingMinutes} min walk · {route.accessible ? 'Accessible route' : 'Standard route'}</span></div>{route.steps.map((step, index) => <div className="route-step" key={step}><b>{index + 1}</b><span>{step}</span></div>)}</> : <div className="empty-state">Select a destination to generate a simulated walking route.</div>}</section></div>; }

const passengerServiceTypes = [
  'Hotel booking','Airport taxi','Parking reservation','Dining order','Shopping assistance',
  'Wheelchair assistance','Elderly passenger assistance','Medical assistance','Unaccompanied minor support',
  'Hearing assistance','Visual assistance','Lost baggage','Delayed baggage','Baggage delivery',
  'Special meal request','Lounge access','Porter service','Language assistance','Airport escort',
  'Pet travel assistance','Accessibility support','Travel document help','Flight disruption support',
  'Refund request','Booking change','Passenger complaint','Service feedback','Lost and found',
  'Airport shuttle','General support'
];

function Services({ smart, act }) {
  const [selected, setSelected] = useState('Wheelchair assistance');
  const [description, setDescription] = useState('');
  const [location, setLocation] = useState('Terminal 1');
  const [items, setItems] = useState([]);
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);
  const load = async () => { try { setItems((await request('/service-requests')).data || []); } catch (error) { setMessage(error.message); } };
  useEffect(() => { load(); const timer = setInterval(load, 15000); return () => clearInterval(timer); }, []);
  const submit = async event => {
    event.preventDefault();
    setBusy(true); setMessage('');
    try {
      await request('/service-requests', { method: 'POST', body: JSON.stringify({ requestType: selected, title: selected, description, location }) });
      setDescription(''); setMessage('Request submitted. You can track its status below.'); await load();
    } catch (error) { setMessage(error.message); }
    finally { setBusy(false); }
  };
  return <div className="service-hub">
    <section className="panel">
      <div className="panel-title"><div><span className="pill blue">30 PASSENGER SERVICES</span><h3>Airport service centre</h3><p className="muted">Choose a service to create a request that appears in the administrator dashboard.</p></div></div>
      <div className="service-type-grid">{passengerServiceTypes.map((type,index) => <button type="button" key={type} className={`service-type ${selected === type ? 'active' : ''}`} onClick={() => setSelected(type)}><span>{String(index+1).padStart(2,'0')}</span><b>{type}</b><small>{selected === type ? 'Selected' : 'Create request'}</small></button>)}</div>
    </section>
    <section className="panel">
      <div className="panel-title"><div><h3>Submit {selected}</h3><p className="muted">Your request is stored in the shared airport operations database.</p></div><span className="pill green">Passenger → Admin sync</span></div>
      <form className="service-request-form" onSubmit={submit}>
        <label>Service<input value={selected} readOnly/></label>
        <label>Airport location<input value={location} onChange={event => setLocation(event.target.value)} placeholder="Terminal, gate or airport area"/></label>
        <label className="full">Details<textarea required minLength="8" value={description} onChange={event => setDescription(event.target.value)} placeholder="Describe what you need, include booking/flight reference if relevant…"/></label>
        {message && <p className="muted full">{message}</p>}
        <button className="primary" disabled={busy || description.trim().length < 8}>{busy ? 'Submitting…' : 'Submit request →'}</button>
      </form>
    </section>
    <section className="panel">
      <div className="panel-title"><div><h3>My service requests</h3><p className="muted">Track administrator acknowledgement and resolution.</p></div><button className="secondary" onClick={load}>Refresh</button></div>
      {items.length ? items.map(item => <article className="service-request-row" key={item.id}><div><b>{item.title || item.request_type}</b><p>{item.description}</p><small>{item.location || 'Location not provided'} · {new Date(item.created_at || item.createdAt).toLocaleString()}</small>{item.admin_response && <p className="admin-response"><b>Admin response:</b> {item.admin_response}</p>}</div><span className={`pill ${item.status === 'Resolved' ? 'green' : item.status === 'Rejected' ? 'red' : 'blue'}`}>{item.status}</span></article>) : <p className="muted">No requests submitted yet.</p>}
    </section>
  </div>;
}

function AdminServiceRequests({ act }) {
  const [items, setItems] = useState([]);
  const [message, setMessage] = useState('');
  const [filter, setFilter] = useState('All');
  const load = async () => { try { setItems((await request('/service-requests')).data || []); setMessage(''); } catch (error) { setMessage(error.message); } };
  useEffect(() => { load(); const timer = setInterval(load, 15000); return () => clearInterval(timer); }, []);
  const save = async (item, changes) => {
    await request(`/service-requests/${item.id}`, { method: 'PATCH', body: JSON.stringify(changes) });
    await load();
  };
  const visible = items.filter(item => filter === 'All' || item.status === filter);
  return <section className="panel">
    <div className="panel-title"><div><span className="pill blue">SHARED PASSENGER WORKFLOW</span><h3>Passenger service requests</h3><p className="muted">Every request submitted from the passenger service centre is managed here.</p></div><button className="secondary" onClick={load}>Refresh requests</button></div>
    <div className="request-summary">{[['Total',items.length],['Open',items.filter(item=>!['Resolved','Rejected'].includes(item.status)).length],['Urgent',items.filter(item=>item.priority==='Urgent').length],['Resolved',items.filter(item=>item.status==='Resolved').length]].map(([label,value])=><div className="stat" key={label}><span>{label}</span><strong>{value}</strong></div>)}</div>
    <label className="request-filter">Filter requests<select value={filter} onChange={event=>setFilter(event.target.value)}>{['All','Submitted','Acknowledged','In progress','Waiting for passenger','Resolved','Rejected'].map(status=><option key={status}>{status}</option>)}</select></label>
    {message && <div className="error">{message}</div>}
    {visible.length ? visible.map(item => <AdminRequestCard key={item.id} item={item} onSave={save}/>) : <p className="muted">No requests in this view.</p>}
  </section>;
}

function AdminRequestCard({ item, onSave }) {
  const [response, setResponse] = useState(item.admin_response || '');
  const [status, setStatus] = useState(item.status || 'Submitted');
  const [priority, setPriority] = useState(item.priority || 'Normal');
  const [busy, setBusy] = useState(false);
  const submit = async () => { setBusy(true); try { await onSave(item, { status, priority, adminResponse: response }); } finally { setBusy(false); } };
  return <article className="admin-request-card">
    <div className="admin-request-heading"><div><span className="pill blue">{item.request_type || item.requestType}</span><h4>{item.title}</h4><p>{item.passenger_name || item.passengerName || 'Passenger'} · {item.passenger_email || item.passengerEmail || item.userId || item.user_id}</p></div><small>{new Date(item.created_at || item.createdAt).toLocaleString()}</small></div>
    <p>{item.description}</p><small className="muted">Location: {item.location || 'Not specified'}</small>
    <div className="admin-request-controls">
      <label>Status<select value={status} onChange={event=>setStatus(event.target.value)}>{['Submitted','Acknowledged','In progress','Waiting for passenger','Resolved','Rejected'].map(value=><option key={value}>{value}</option>)}</select></label>
      <label>Priority<select value={priority} onChange={event=>setPriority(event.target.value)}>{['Low','Normal','High','Urgent'].map(value=><option key={value}>{value}</option>)}</select></label>
      <label className="response-field">Admin response<textarea value={response} onChange={event=>setResponse(event.target.value)} placeholder="Add an update for the passenger…"/></label>
      <button className="primary" disabled={busy} onClick={submit}>{busy ? 'Saving…' : 'Save update for passenger'}</button>
    </div>
  </article>;
}

function FlightBoard({ flights }) { return <section className="panel"><div className="panel-title"><div><h3>Live flight information</h3><p className="muted">Simulated operational data · updated {new Date().toLocaleTimeString()}</p></div><span className="pill green">LIVE</span></div><div className="table-wrap"><table><thead><tr><th>Flight</th><th>Route</th><th>Scheduled</th><th>Terminal</th><th>Gate</th><th>Status</th></tr></thead><tbody>{flights.map(flight => <tr key={flight.id}><td><b>{flight.number}</b><small>{flight.airline}</small></td><td>{flight.origin} → {flight.destination}</td><td>{flight.scheduled}<small>Est. {flight.estimated}</small></td><td>{flight.terminal}</td><td>{flight.gate}</td><td><span className={`pill ${flight.status === 'Delayed' ? 'red' : flight.status === 'Boarding' ? 'blue' : 'green'}`}>{flight.status}</span></td></tr>)}</tbody></table></div></section>; }

function Trips({ me, flights, act }) { return <section className="panel"><div className="panel-title"><h3>My trips</h3><span className="muted">{me?.bookings?.length || 0} booking(s)</span></div>{me?.bookings?.map(booking => { const flight = flights.find(item => item.id === booking.flightId); return <div className="booking-row" key={booking.id}><div className="flight-code">{flight?.number}</div><div><b>{flight?.origin} → {flight?.destination}</b><p>PNR {booking.pnr} · Seat {booking.seat} · {booking.baggageStatus}</p></div><span className="pill green">{booking.status}</span>{!booking.checkedIn && <button className="secondary" onClick={() => act(() => request(`/bookings/${booking.id}/check-in`, { method: 'POST' }))}>Check in</button>}</div>; })}</section>; }
function Baggage({ me }) { return <section className="panel"><div className="panel-title"><h3>Baggage tracking</h3><Icons.bag/></div>{me?.bookings?.map(booking => <div className="baggage-card" key={booking.id}><div className="bag-icon"><Icons.bag/></div><div><b>{booking.baggage}</b><p>Booking {booking.pnr}</p></div><span className="pill blue">{booking.baggageStatus}</span></div>)}</section>; }

function Operations({ dashboard, flights, act }) { return <><div className="stat-grid">{[['Passengers', dashboard?.stats.passengers?.toLocaleString(), '↑ 8.4%'], ['Departures', dashboard?.stats.departures, 'Today'], ['Active flights', dashboard?.stats.activeFlights, 'Live'], ['Revenue', dashboard ? `₹${(dashboard.stats.revenue / 100000).toFixed(1)}L` : '—', 'This month']].map(([label, value, foot]) => <div className="stat" key={label}><span>{label}</span><strong>{value ?? '—'}</strong><small>{foot}</small></div>)}</div><div className="grid two"><section className="panel"><div className="panel-title"><h3>Operational alerts</h3><Icons.shield/></div>{dashboard?.alerts?.map(alert => <div className="alert" key={alert.title}><span className="alert-mark">!</span><div><b>{alert.title}</b><p>{alert.body}</p></div></div>)}</section><section className="panel"><div className="panel-title"><h3>Flight actions</h3></div>{flights.map(flight => <div className="flight-action" key={flight.id}><div><b>{flight.number}</b><p>{flight.origin} → {flight.destination}</p></div><select value={flight.status} onChange={e => act(() => request(`/flights/${flight.id}`, { method: 'PATCH', body: JSON.stringify({ status: e.target.value }) }))}>{['Scheduled', 'Boarding', 'Delayed', 'Departed', 'Cancelled'].map(status => <option key={status}>{status}</option>)}</select></div>)}</section></div></>; }

function ControlRoom({ smart, flights }) { return <><div className="control-banner"><div><span className="pill blue">NETWORK OPERATIONS · SIMULATED</span><h3>Airport control room</h3><p>Cross-functional operational health across the selected demo airport.</p></div><div className="control-health"><i/> Systems nominal</div></div><div className="stat-grid">{[['Gate utilization', '68%', '9 available'], ['Terminal occupancy', '72%', 'T1 · simulated'], ['Open incidents', smart?.incidents?.length || 0, 'Monitoring'], ['Queue wait', `${Math.max(...(smart?.queues || [{ wait: 0 }]).map(q => q.wait))} min`, 'Peak security']].map(([label, value, foot]) => <div className="stat" key={label}><span>{label}</span><strong>{value}</strong><small>{foot}</small></div>)}</div><div className="grid two"><FlightBoard flights={flights}/><section className="panel"><div className="panel-title"><h3>Operational timeline</h3><Icons.control/></div>{['06:40 · SF 101 boarding at A12', '09:20 · SF 204 scheduled departure', 'Security queue peak review · 08:30', 'SF 330 weather disruption monitoring'].map(item => <div className="timeline-item" key={item}><i/><span>{item}</span></div>)}</section></div></>; }

function QueueBoard({ smart, act }) { return <section className="panel"><div className="panel-title"><div><h3>Smart queue management</h3><p className="muted">Waiting times are simulated estimates, not sensor measurements.</p></div><span className="pill blue">DEMO QUEUES</span></div><div className="queue-grid">{smart?.queues?.map(queue => <div className="queue-card" key={queue.id}><div className="queue-head"><b>{queue.name}</b><span className={`pill ${queue.open ? 'green' : 'red'}`}>{queue.open ? 'OPEN' : 'CLOSED'}</span></div><strong>{queue.wait} min</strong><span>Estimated wait · {queue.length} people</span><small>{queue.counters}</small><button className="secondary" onClick={() => act(() => request(`/smart/queues/${queue.id}`, { method: 'PATCH', body: JSON.stringify({ open: !queue.open }) }))}>{queue.open ? 'Close counter' : 'Open counter'}</button></div>)}</div></section>; }

function Verification({ smart, act }) { return <section className="panel"><div className="panel-title"><div><h3>Document verification desk</h3><p className="muted">Simulation only. No biometric identity decision is made by SkyFlow.</p></div><Icons.verification/></div>{smart?.verification ? <div className="verification-card"><div className="verification-status"><span className="pill blue">{smart.verification.status}</span><b>Passenger document review</b><p>{smart.verification.documents.join(' · ')}</p><small>{smart.verification.note}</small></div><div className="verification-actions"><button className="secondary" onClick={() => act(() => request(`/smart/verification/${smart.verification.id}`, { method: 'PATCH', body: JSON.stringify({ status: 'Approved' }) }))}>Approve review</button><button className="secondary" onClick={() => act(() => request(`/smart/verification/${smart.verification.id}`, { method: 'PATCH', body: JSON.stringify({ status: 'Needs attention' }) }))}>Needs attention</button></div></div> : <div className="empty-state">No verification records in the selected airport.</div>}</section>; }
function Assistance({ smart, act }) { return <section className="panel"><div className="panel-title"><div><h3>Assistance operations</h3><p className="muted">Assign and close passenger support requests.</p></div><Icons.help/></div>{smart?.assistance?.map(item => <div className="assistance-row" key={item.id}><div className="avatar">{item.type[0]}</div><div><b>{item.type}</b><p>{item.location} · {item.assignedTo || 'Unassigned'}</p></div><span className="pill blue">{item.status}</span><button className="secondary" onClick={() => act(() => request(`/smart/assistance/${item.id}`, { method: 'PATCH', body: JSON.stringify({ status: 'Completed', assignedTo: 'Operations desk' }) }))}>Complete</button></div>)}</section>; }
function Passengers({ dashboard }) { return <section className="panel"><div className="panel-title"><h3>Recent bookings</h3><Icons.users/></div>{dashboard?.recentBookings?.map(booking => <div className="booking-row" key={booking.id}><div className="avatar">{booking.passenger[0]}</div><div><b>{booking.passenger}</b><p>PNR {booking.pnr} · Seat {booking.seat}</p></div><span className="pill green">{booking.status}</span></div>)}</section>; }

function AirportPicker({ label, value, onChange }) { const [options, setOptions] = useState([]); const search = async text => { onChange(text); if (text.length < 2) return setOptions([]); try { setOptions((await request(`/airports?q=${encodeURIComponent(text)}`)).data); } catch { setOptions([]); } }; return <label className="airport-picker">{label}<input value={value} onChange={e => search(e.target.value)} placeholder="Airport, city or IATA" autoComplete="off"/>{options.length > 0 && <div className="airport-options">{options.map(a => <button type="button" key={a.code} onClick={() => { onChange(`${a.code} · ${a.city}`); setOptions([]); }}>{a.code} <span>{a.city} · {a.name}</span></button>)}</div>}</label>; }
function FlightSearch() { const [form, setForm] = useState({ origin: 'DEL · New Delhi', destination: 'HYD · Hyderabad', date: '2026-11-03', returnDate: '', trip: 'one-way', adults: 1, children: 0, travelClass: 'Economy' }); const [filters, setFilters] = useState({ airline: '', maxPrice: '', stops: '', sort: 'earliest' }); const [results, setResults] = useState([]); const [message, setMessage] = useState(''); const code = value => value.split(' ')[0]; const search = async e => { e.preventDefault(); setMessage(''); if (code(form.origin) === code(form.destination)) return setMessage('Choose different origin and destination airports.'); if (form.trip === 'round-trip' && !form.returnDate) return setMessage('Select a return date for a round trip.'); if (form.children < 0 || form.adults < 1 || Number(form.adults) + Number(form.children) > 9) return setMessage('Enter 1–9 passengers with at least one adult.'); try { const query = new URLSearchParams({ origin: code(form.origin), destination: code(form.destination), date: form.date, travelClass: form.travelClass, sort: filters.sort }); if (filters.airline) query.set('airline', filters.airline); if (filters.maxPrice) query.set('maxPrice', filters.maxPrice); if (filters.stops) query.set('stops', filters.stops); setResults((await request(`/flights?${query}`)).data); } catch (err) { setMessage(err.message); } }; const swap = () => setForm({ ...form, origin: form.destination, destination: form.origin }); return <><section className="panel search-panel"><div className="panel-title"><div><span className="pill blue">PHASE 2 · LIVE SEARCH</span><h3>Find your next flight</h3><p className="muted">Search uses the SkyFlow airport database and simulated schedules.</p></div><span className="pill green">No booking yet</span></div><form onSubmit={search} className="flight-search-form"><div className="route-fields"><AirportPicker label="From" value={form.origin} onChange={origin => setForm({ ...form, origin })}/><button type="button" className="swap-button" onClick={swap}>⇄</button><AirportPicker label="To" value={form.destination} onChange={destination => setForm({ ...form, destination })}/></div><div className="search-grid"><label>Trip type<select value={form.trip} onChange={e => setForm({ ...form, trip: e.target.value })}><option value="one-way">One-way</option><option value="round-trip">Round trip</option></select></label><label>Departure<input type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })}/></label>{form.trip === 'round-trip' && <label>Return<input type="date" value={form.returnDate} onChange={e => setForm({ ...form, returnDate: e.target.value })}/></label>}<label>Adults<input type="number" min="1" max="9" value={form.adults} onChange={e => setForm({ ...form, adults: e.target.value })}/></label><label>Children<input type="number" min="0" max="9" value={form.children} onChange={e => setForm({ ...form, children: e.target.value })}/></label><label>Class<select value={form.travelClass} onChange={e => setForm({ ...form, travelClass: e.target.value })}>{['Economy','Premium Economy','Business','First Class'].map(x => <option key={x}>{x}</option>)}</select></label></div>{message && <div className="error">{message}</div>}<button className="primary">Search flights →</button></form></section><section className="panel results-panel"><div className="panel-title"><div><h3>Available flights</h3><p className="muted">{results.length} matching result(s) · fares are simulated demo prices</p></div><div className="result-tools"><select value={filters.sort} onChange={e => setFilters({ ...filters, sort: e.target.value })}><option value="earliest">Earliest departure</option><option value="cheapest">Cheapest</option><option value="fastest">Fastest</option></select><select value={filters.stops} onChange={e => setFilters({ ...filters, stops: e.target.value })}><option value="">All stops</option><option value="nonstop">Non-stop</option><option value="connecting">Connecting</option></select></div></div>{results.length ? results.map(f => <div className="flight-result" key={f.id}><div><b>{f.airline}</b><small>{f.number} · {f.aircraft}</small></div><div><strong>{f.scheduled}</strong><span>{f.origin} → {f.destination}</span></div><div><strong>{f.arrival}</strong><span>{f.durationMinutes} min · {f.stopsLabel}</span></div><div><span>{f.terminal} · Gate {f.gate || 'TBC'}</span><small>{f.baggageAllowance} baggage · {f.availableSeats} seats</small></div><div className="fare"><b>₹{f.fare.toLocaleString()}</b><span className="pill green">{f.status}</span><button className="secondary" disabled>Booking in Phase 3</button></div></div>) : <div className="empty-state">Search a route and date to view matching flights.</div>}</section></>; }
function FlightManagement({ flights, act }) { const blank = { number: '', origin: 'DEL', destination: 'HYD', date: '2026-11-03', scheduled: '15:00', arrival: '17:00', terminal: 'T1', gate: 'C10', aircraft: 'A320', seats: 180, fare: 7000, durationMinutes: 120, travelClass: 'Economy', baggageAllowance: '20 kg' }; const [form, setForm] = useState(blank); const [editing, setEditing] = useState(null); const save = async e => { e.preventDefault(); await act(() => request(editing ? `/flights/${editing}` : '/flights', { method: editing ? 'PUT' : 'POST', body: JSON.stringify(form) })); setEditing(null); setForm(blank); }; return <><section className="panel"><div className="panel-title"><div><span className="pill blue">ADMIN ONLY</span><h3>{editing ? 'Edit flight' : 'Add flight'}</h3><p className="muted">Validated schedules and gate allocation safeguards are active.</p></div></div><form onSubmit={save} className="admin-flight-form">{[['number','Flight number'],['origin','Origin IATA'],['destination','Destination IATA'],['date','Date'],['scheduled','Departure HH:MM'],['arrival','Arrival HH:MM'],['terminal','Terminal'],['gate','Gate'],['aircraft','Aircraft'],['seats','Seat capacity'],['fare','Fare']].map(([key,label]) => <label key={key}>{label}<input required value={form[key]} onChange={e => setForm({ ...form, [key]: e.target.value })} type={['seats','fare'].includes(key) ? 'number' : key === 'date' ? 'date' : 'text'}/></label>)}<button className="primary">{editing ? 'Save flight' : 'Create flight'}</button>{editing && <button type="button" className="secondary" onClick={() => { setEditing(null); setForm(blank); }}>Cancel</button>}</form></section><section className="panel"><div className="panel-title"><h3>Flight inventory</h3><span className="muted">{flights.length} records</span></div>{flights.map(f => <div className="flight-admin-row" key={f.id}><div><b>{f.number}</b><p>{f.origin} → {f.destination} · {f.date} · {f.scheduled}</p></div><span className={`pill ${f.status === 'Delayed' ? 'red' : 'green'}`}>{f.status}</span><button className="secondary" onClick={() => { setEditing(f.id); setForm(f); }}>Edit</button><select value={f.status} onChange={e => act(() => request(`/flights/${f.id}`, { method: 'PATCH', body: JSON.stringify({ status: e.target.value }) }))}>{['Scheduled','Boarding','Delayed','Cancelled','Departed'].map(s => <option key={s}>{s}</option>)}</select><button className="danger-button" onClick={() => act(() => request(`/flights/${f.id}`, { method: 'DELETE' }))}>Delete</button></div>)}</section></>; }
function BookingCheckout({ flight, onClose }) { const [passengers, setPassengers] = useState([{ fullName: '', dateOfBirth: '', contactEmail: '', contactPhone: '', documentType: 'Passport', documentNumber: '' }]); const [seats, setSeats] = useState([]); const [seatMap, setSeatMap] = useState([]); const [quote, setQuote] = useState(null); const [outcome, setOutcome] = useState('success'); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false); useEffect(() => { request(`/flights/${flight.id}/seats`).then(result => setSeatMap(result.data)).catch(error => setMessage(error.message)); }, [flight.id]); const updatePassenger = (index, key, value) => setPassengers(passengers.map((item, itemIndex) => itemIndex === index ? { ...item, [key]: value } : item)); const calculate = async () => { try { setMessage(''); setQuote((await request('/bookings/quote', { method: 'POST', body: JSON.stringify({ flightId: flight.id, passengers }) })).data); } catch (error) { setMessage(error.message); } }; const submit = async () => { if (seats.length !== passengers.length) return setMessage('Select one seat for every passenger.'); setBusy(true); try { const result = await request('/bookings', { method: 'POST', body: JSON.stringify({ flightId: flight.id, passengers, seats, paymentOutcome: outcome, idempotencyKey: `web-${Date.now()}-${Math.random()}` }) }); setMessage(`Booking confirmed. Your PNR is ${result.data.pnr}.`); } catch (error) { setMessage(error.message); } finally { setBusy(false); } }; return <section className="panel booking-checkout"><div className="panel-title"><div><span className="pill blue">SIMULATED BOOKING</span><h3>Complete your journey · {flight.number}</h3><p className="muted">{flight.origin} → {flight.destination} · {flight.scheduled}–{flight.arrival} · {flight.baggageAllowance} baggage</p></div><button className="secondary" onClick={onClose}>Back to results</button></div>{passengers.map((item, index) => <div className="passenger-form" key={index}><b>Passenger {index + 1}</b><div className="form-grid"><input placeholder="Full name" value={item.fullName} onChange={e => updatePassenger(index, 'fullName', e.target.value)}/><input type="date" value={item.dateOfBirth} onChange={e => updatePassenger(index, 'dateOfBirth', e.target.value)}/><input placeholder="Email" type="email" value={item.contactEmail} onChange={e => updatePassenger(index, 'contactEmail', e.target.value)}/><input placeholder="Phone" value={item.contactPhone} onChange={e => updatePassenger(index, 'contactPhone', e.target.value)}/><select value={item.documentType} onChange={e => updatePassenger(index, 'documentType', e.target.value)}><option>Passport</option><option>National ID</option><option>Visa</option></select><input placeholder="Document number (demo only)" value={item.documentNumber} onChange={e => updatePassenger(index, 'documentNumber', e.target.value)}/></div></div>)}<button className="secondary" onClick={() => setPassengers([...passengers, { fullName: '', dateOfBirth: '', contactEmail: '', contactPhone: '', documentType: 'Passport', documentNumber: '' }])}>+ Add passenger</button><h4>Select seats</h4><div className="seat-map">{seatMap.map(item => <button key={item.seat} disabled={item.status !== 'available'} className={`seat ${item.status} ${seats.includes(item.seat) ? 'selected' : ''}`} onClick={() => setSeats(seats.includes(item.seat) ? seats.filter(seat => seat !== item.seat) : seats.length < passengers.length ? [...seats, item.seat] : seats)}>{item.seat}</button>)}</div><div className="checkout-actions"><button className="secondary" onClick={calculate}>Calculate fare</button>{quote && <div className="fare-breakdown">Base ₹{quote.baseFare.toLocaleString()} · Taxes ₹{quote.taxes.toLocaleString()} · Total <b>₹{quote.totalAmount.toLocaleString()}</b></div>}<select value={outcome} onChange={e => setOutcome(e.target.value)}><option value="success">Simulated payment succeeds</option><option value="failure">Simulated payment fails</option></select><button className="primary" disabled={busy} onClick={submit}>{busy ? 'Processing…' : 'Confirm demo payment'}</button></div>{message && <div className={message.includes('confirmed') ? 'success' : 'error'}>{message}</div>}</section>; }
function FlightSearchPhase3() { const [results, setResults] = useState([]); const [selected, setSelected] = useState(null); const [origin, setOrigin] = useState('DEL'); const [destination, setDestination] = useState('HYD'); const [date, setDate] = useState('2026-11-03'); const search = async event => { event.preventDefault(); setResults((await request(`/flights?origin=${origin}&destination=${destination}&date=${date}`)).data); }; return selected ? <BookingCheckout flight={selected} onClose={() => setSelected(null)}/> : <><section className="panel"><div className="panel-title"><div><span className="pill blue">PHASE 3 · BOOKING</span><h3>Find and book your flight</h3><p className="muted">Demo booking only. No real airline or payment-provider connection is configured.</p></div></div><form className="booking-search" onSubmit={search}><label>From<input value={origin} onChange={e => setOrigin(e.target.value.toUpperCase())}/></label><label>To<input value={destination} onChange={e => setDestination(e.target.value.toUpperCase())}/></label><label>Departure<input type="date" value={date} onChange={e => setDate(e.target.value)}/></label><button className="primary">Search</button></form></section><section className="panel"><div className="panel-title"><h3>Bookable results</h3><span className="muted">{results.length} result(s)</span></div>{results.map(flight => <div className="flight-result" key={flight.id}><div><b>{flight.airline}</b><small>{flight.number}</small></div><div><strong>{flight.scheduled} → {flight.arrival}</strong><span>{flight.origin} → {flight.destination} · {flight.durationMinutes} min</span></div><div><span>{flight.baggageAllowance} baggage</span><small>Terminal {flight.terminal} · Gate {flight.gate || 'TBC'}</small></div><div className="fare"><b>₹{flight.fare.toLocaleString()}</b><button className="primary" onClick={() => setSelected(flight)}>Select flight</button></div></div>)}{!results.length && <div className="empty-state">Search a route to start a demo booking.</div>}</section></>; }
function PassengerBookings({ me, flights, act }) { const cancel = booking => act(() => request(`/bookings/${booking.id}/cancel`, { method: 'POST' })); return <section className="panel"><div className="panel-title"><h3>My bookings</h3><span className="muted">Only your personal bookings are shown</span></div>{me?.bookings?.map(booking => { const flight = flights.find(item => item.id === booking.flightId); return <article className="booking-card" key={booking.id}><div><span className="pill blue">PNR {booking.pnr}</span><h3>{flight?.origin} → {flight?.destination}</h3><p>{flight?.number} · {flight?.date} · {flight?.scheduled}–{flight?.arrival}</p><p>Passengers: {booking.passengers?.map(item => item.fullName).join(', ') || booking.passenger} · Seats: {(booking.seats || [booking.seat]).join(', ')}</p><p>Payment: {booking.paymentStatus || 'Completed'} · Total: ₹{Number(booking.totalAmount || 0).toLocaleString()}</p></div><div className="checkout-actions"><button className="secondary" onClick={() => window.print()}>Print itinerary</button>{booking.status !== 'Cancelled' && <button className="danger-button" onClick={() => cancel(booking)}>Cancel demo booking</button>}</div></article>; })}</section>; }
function AdminBookings() { const [query, setQuery] = useState(''); const [items, setItems] = useState([]); const [message, setMessage] = useState(''); const load = async () => { try { setItems((await request(`/bookings?q=${encodeURIComponent(query)}`)).data); } catch (error) { setMessage(error.message); } }; useEffect(() => { load(); }, []); return <section className="panel"><div className="panel-title"><div><h3>Booking operations</h3><p className="muted">Admin view · payment methods are demo-only and credentials are never shown.</p></div></div><div className="booking-search"><input placeholder="Search PNR, passenger or flight" value={query} onChange={e => setQuery(e.target.value)}/><button className="primary" onClick={load}>Search bookings</button></div>{message && <div className="error">{message}</div>}{items.map(item => <div className="booking-admin-row" key={item.id}><div><b>{item.pnr}</b><p>{item.passenger} · {item.payment?.method || 'Demo payment'} · ₹{Number(item.totalAmount || 0).toLocaleString()}</p></div><span className="pill blue">{item.status}</span><select value={item.status} onChange={async e => { await request(`/bookings/${item.id}/status`, { method: 'PATCH', body: JSON.stringify({ status: e.target.value }) }); load(); }}><option>Confirmed</option><option>Checked-in</option><option>Cancelled</option><option>Completed</option><option>Refund pending</option></select></div>)}</section>; }
FlightSearch = FlightSearchPhase3;
Trips = PassengerBookings;
Passengers = AdminBookings;
function PassengerLogin({ onLogin }) { const [adminMode, setAdminMode] = useState(false); const [registerMode, setRegisterMode] = useState(false); const [menuOpen, setMenuOpen] = useState(false); const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const submit = async event => { event.preventDefault(); setError(''); setMessage(''); try { if (registerMode) { const result = await request('/auth/register', { method: 'POST', body: JSON.stringify({ name, email, password }) }); setMessage(result.message); setRegisterMode(false); return; } const result = await request('/auth/login', { method: 'POST', body: JSON.stringify({ email, password }) }); if (!adminMode && result.user.role !== 'passenger') throw Error('Use Administrator Login from the menu for airport staff access.'); localStorage.token = result.token; onLogin(result.user); } catch (err) { setError(err.message); } }; const forgot = async () => { try { const result = await request('/auth/forgot-password', { method: 'POST', body: JSON.stringify({ email }) }); setMessage(result.message); } catch (err) { setError(err.message); } }; return <main className="auth"><div className="runway"><div className="plane-float">✈</div></div><section className="login-card"><button className="menu-button" aria-label="Open menu" onClick={() => setMenuOpen(!menuOpen)}>☰</button>{menuOpen && <div className="auth-menu"><button onClick={() => { setAdminMode(true); setRegisterMode(false); setMenuOpen(false); }}>Administrator Login</button><button onClick={() => { setAdminMode(false); setRegisterMode(false); setMenuOpen(false); }}>Passenger Login</button></div>}<div className="brand"><Icons.plane/><span>SKYFLOW</span></div><p className="eyebrow">SMART INTERNATIONAL AIRPORT</p><h1>{registerMode ? 'Create your passenger account.' : adminMode ? 'Airport operations, connected.' : 'Travel, orchestrated.'}</h1><p className="muted">{adminMode ? 'Authorized personnel only.' : 'A connected airport experience for every journey.'}</p><form onSubmit={submit}>{registerMode && <label>Full name<input required value={name} onChange={e => setName(e.target.value)}/></label>}<label>Email<input required value={email} onChange={e => setEmail(e.target.value)} type="email" placeholder={adminMode ? 'Administrator email' : 'you@example.com'}/></label><label>Password<input required value={password} onChange={e => setPassword(e.target.value)} type="password" minLength="8"/></label>{error && <div className="error">{error}</div>}{message && <div className="success">{message}</div>}<button className="primary">{registerMode ? 'Create passenger account' : 'Sign in to SkyFlow →'}</button></form>{!adminMode && !registerMode && <div className="auth-links"><button onClick={() => setRegisterMode(true)}>Create passenger account</button><button onClick={forgot}>Forgot password?</button></div>}<small>{adminMode ? 'Administrator access is provisioned by a Super Administrator.' : 'Passenger portal · operational data is labelled when simulated.'}</small></section></main>; }
function Root() { const [user, setUser] = useState(() => JSON.parse(localStorage.user || 'null')); useEffect(() => { const expired = () => setUser(null); window.addEventListener('skyflow:session-expired', expired); return () => window.removeEventListener('skyflow:session-expired', expired); }, []); const logout = async () => { try { if (localStorage.token) await request('/auth/logout', { method: 'POST' }); } finally { localStorage.clear(); setUser(null); } }; if (window.location.hash.includes('type=recovery') && window.location.hash.includes('access_token=')) return <PasswordRecovery/>; if (!user) return <SupabaseLogin onLogin={item => { localStorage.user = JSON.stringify(item); setUser(item); }}/>; return <App user={user} onLogout={logout}/>; }
// The public auth surface is intentionally Supabase-backed; the legacy demo login above is not rendered.
function PasswordRecovery() { const [password,setPassword]=useState(''); const [message,setMessage]=useState(''); const [error,setError]=useState(''); const [busy,setBusy]=useState(false); const params=new URLSearchParams(window.location.hash.slice(1)); const accessToken=params.get('access_token'); const submit=async event=>{event.preventDefault();setBusy(true);setError('');try{const response=await fetch(`${API}/auth/change-password`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${accessToken}`},body:JSON.stringify({password})});const result=await response.json();if(!response.ok)throw Error(result.error||'Password reset failed');setMessage('Password updated. Sign in with your new password.');window.history.replaceState(null,'',window.location.pathname);}catch(err){setError(err.message);}finally{setBusy(false);}}; return <main className="auth"><div className="runway"/><section className="login-card"><div className="brand"><Icons.plane/><span>SKYFLOW</span></div><p className="eyebrow">ACCOUNT SECURITY</p><h1>Choose a new password.</h1><form onSubmit={submit}><label>New password<input autoComplete="new-password" type="password" minLength="12" required value={password} onChange={event=>setPassword(event.target.value)}/></label>{error&&<div className="error">{error}</div>}{message&&<div className="success">{message}</div>}<button className="primary" disabled={busy||!accessToken}>{busy?'Updating…':'Update password'}</button></form><small>Use at least 12 characters. Recovery is verified by Supabase Auth.</small></section></main>; }
function SupabaseLogin({ onLogin }) {
  const [adminMode, setAdminMode] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [registerMode, setRegisterMode] = useState(false);
  const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState('');
  const [error, setError] = useState(''); const [message, setMessage] = useState('');
  const submit = async event => { event.preventDefault(); setError(''); setMessage(''); try { if (registerMode) { const result = await request('/auth/register', { method: 'POST', body: JSON.stringify({ name, email, password }) }); setMessage(result.message); setRegisterMode(false); return; } const result = await request('/auth/login', { method: 'POST', body: JSON.stringify({ email, password }) }); if (!adminMode && result.user.role !== 'passenger') throw Error('Use Administrator Login for airport staff access.'); localStorage.token = result.token; localStorage.refreshToken = result.refreshToken || ''; onLogin(result.user); } catch (err) { setError(err.message); } };
  const forgot = async () => { setError(''); try { setMessage((await request('/auth/forgot-password', { method: 'POST', body: JSON.stringify({ email }) })).message); } catch (err) { setError(err.message); } };
  return <main className="auth"><div className="runway"><div className="plane-float">✈</div></div><section className="login-card"><button className="menu-button" aria-label="Open menu" onClick={() => setMenuOpen(!menuOpen)}>☰</button>{menuOpen && <div className="auth-menu"><button onClick={() => { setAdminMode(true); setRegisterMode(false); setMenuOpen(false); }}>Administrator Login</button><button onClick={() => { setAdminMode(false); setRegisterMode(false); setMenuOpen(false); }}>Passenger Login</button></div>}<div className="brand"><Icons.plane/><span>SKYFLOW</span></div><p className="eyebrow">SMART INTERNATIONAL AIRPORT</p><h1>{registerMode ? 'Create your passenger account.' : adminMode ? 'Airport operations, connected.' : 'Travel, orchestrated.'}</h1><p className="muted">{adminMode ? 'Authorized personnel only.' : 'A connected airport experience for every journey.'}</p><form onSubmit={submit}>{registerMode && <label>Full name<input required value={name} onChange={e => setName(e.target.value)}/></label>}<label>Email<input required value={email} onChange={e => setEmail(e.target.value)} type="email" placeholder={adminMode ? 'Administrator email' : 'you@example.com'}/></label><label>Password<input required value={password} onChange={e => setPassword(e.target.value)} type="password" minLength="8"/></label>{error && <div className="error">{error}</div>}{message && <div className="success">{message}</div>}<button className="primary">{registerMode ? 'Create passenger account' : 'Sign in to SkyFlow →'}</button></form>{!adminMode && !registerMode && <div className="auth-links"><button onClick={() => setRegisterMode(true)}>Create passenger account</button><button onClick={forgot}>Forgot password?</button></div>}<small>{adminMode ? 'Administrator access is provisioned by a Super Administrator.' : 'Protected by Supabase Auth · account access is verified server-side.'}</small></section></main>;
}
createRoot(document.getElementById('root')).render(<Root/>);
